-- Argile blanche → accord_olfactif (matière minérale olfactive)
UPDATE raw_materials SET category = 'accord_olfactif' WHERE name = 'Argile blanche';

-- Birch Tar North American → resinoid (goudron de bouleau)
UPDATE raw_materials SET category = 'resinoid' WHERE name = 'Birch Tar North American';

-- Borrachero et Borrachero (Brugmansia) → huile_essentielle
UPDATE raw_materials SET category = 'huile_essentielle' WHERE name IN ('Borrachero', 'Borrachero (Brugmansia)');

-- Bronze Note → accord_olfactif (note métallique créative)
UPDATE raw_materials SET category = 'accord_olfactif' WHERE name = 'Bronze Note';

-- Feuille d'oranger sèche → huile_essentielle
UPDATE raw_materials SET category = 'huile_essentielle' WHERE name = "Feuille d'oranger sèche";

-- Juniper (Genièvre) → huile_essentielle
UPDATE raw_materials SET category = 'huile_essentielle' WHERE name = 'Juniper (Genièvre)';

-- Millet chaud → accord_olfactif (note céréalière)
UPDATE raw_materials SET category = 'accord_olfactif' WHERE name = 'Millet chaud';

-- Oud (Agarwood) → resinoid
UPDATE raw_materials SET category = 'resinoid' WHERE name = 'Oud (Agarwood)';

-- Test Molecule 1, Test Molecule 2 → molecule_isolee
UPDATE raw_materials SET category = 'molecule_isolee' WHERE name IN ('Test Molecule 1', 'Test Molecule 2');

-- Vanilla Pompona → absolue (absolue de vanille)
UPDATE raw_materials SET category = 'absolue' WHERE name = 'Vanilla Pompona';

